
import type { GiftCardNotificationDeliveryAttempt } from './GiftCardNotificationDeliveryAttempt.js';
import type { GiftCardNotificationProviderOutcome } from './GiftCardNotificationProviderOutcome.js';

export type GiftCardNotification = { /** RFC3339 timestamp. Format: date-time. */ "created_at": string; /** Included on notification retrieval. Contains the most recent sending attempts and signed provider outcomes, newest first. A failed attempt describes the send call; use notification.status to determine whether acceptance remains unknown. */ "delivery"?: { /** maxItems: 20. */ "attempts": Array<GiftCardNotificationDeliveryAttempt>; "has_more_attempts": boolean; "has_more_provider_outcomes": boolean; /** maxItems: 50. */ "provider_outcomes": Array<GiftCardNotificationProviderOutcome>; }; "gift_card_id": string; "gift_card_notification_id": string; "recipient": { /** Format: email. maxLength: 254. */ "email": string; /** maxLength: 200. */ "message"?: string; /** maxLength: 255. */ "name"?: string; /** Optional whole-second send time between now and 90 days from now. Format: date-time. */ "send_at"?: string; }; "resend_of_notification_id"?: string; /** RFC3339 timestamp. Format: date-time. */ "sent_at"?: string; "status": "scheduled" | "queued" | "sending" | "sent" | "failed" | "unknown" | "bounced" | "canceled" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "updated_at": string; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "version": string; };
